const secret = $vars.MAGNIFIC_WEBHOOK_SECRET || '';
const headers = $json.headers || {};
const body = $json.body || $json;
// Magnific firma via header (ajustar nombre si difiere). Si no hay secret configurado, no bloquea.
const recibido = headers['x-magnific-signature'] || headers['x-webhook-secret'] || '';
if (secret && recibido && recibido !== secret) {
  throw new Error('Firma de webhook inválida');
}
const data = body.data || body;
const task_id = data.task_id || '';
const status = (data.status || '').toUpperCase();
// el id del LoRA entrenado: segun doc viene en data; cubrimos variantes
const lora_id = data.lora_id || data.id || (Array.isArray(data.generated)&&data.generated[0]) || '';
return [{ json: { task_id, status, lora_id, raw: JSON.stringify(data).slice(0,500) } }];

const evt = $('Validar y parsear').item.json;
const rows = $input.all().map(i=>i.json);
// durante 'entrenando' guardamos task_id en lora_id
const avatar = rows.find(a => a.lora_id === evt.task_id && a.lora_estado === 'entrenando');
if (!avatar) {
  // no encontrado: devolver flag para avisar sin romper
  return [{ json: { encontrado:false, task_id:evt.task_id, status:evt.status } }];
}
const exito = evt.status === 'COMPLETED' || evt.status === 'SUCCESS' || evt.status === 'CREATED';
return [{ json: {
  encontrado:true,
  avatar_id: avatar.avatar_id,
  nombre: avatar.nombre || avatar.avatar_id,
  nuevo_estado: exito ? 'entrenado' : 'pendiente',
  lora_id_final: exito ? (evt.lora_id || evt.task_id) : '',
  status: evt.status
} }];

const j=$('Emparejar avatar').item.json;
const token=$vars.TELEGRAM_BOT_TOKEN;
const admin=$vars.USER_ID_TELEGRAM;
const ok = j.nuevo_estado==='entrenado';
const txt = ok
  ? `✅ LoRA de *${j.nombre}* entrenado y listo para usar en Mystic.`
  : `⚠️ El entrenamiento de *${j.nombre}* no se completó (status: ${j.status}). Quedó en 'pendiente', puedes reintentar con /entrenar_lora.`;
await this.helpers.httpRequest({method:'POST',url:`https://api.telegram.org/bot${token}/sendMessage`,
  body:{chat_id:admin,text:txt,parse_mode:'Markdown'},json:true});
return [{json:{ok:true}}];

const j=$('Emparejar avatar').item.json;
const token=$vars.TELEGRAM_BOT_TOKEN;
const admin=$vars.USER_ID_TELEGRAM;
await this.helpers.httpRequest({method:'POST',url:`https://api.telegram.org/bot${token}/sendMessage`,
  body:{chat_id:admin,text:`ℹ️ Webhook Magnific recibido (task ${j.task_id||'?'}, status ${j.status||'?'}) pero no encontré un avatar en estado 'entrenando' con ese task_id.`},json:true});
return [{json:{ok:true}}];
